# Generated by verification/install_selection.rs. Used before any tool is installed.
validate_override() {
    case "$1" in
        stable|preview) observed=named ;;
        *[!A-Za-z0-9.-]*|'') observed=unsafe ;;
        *)
            if printf '%s\n' "$1" | grep -Eq '^v[0-9]+[.][0-9]+[.][0-9]+(-[A-Za-z0-9-]+([.][A-Za-z0-9-]+)*)?$'; then
                observed=exact
            else
                observed=invalid
            fi ;;
    esac
    case "$observed" in
        named) return 0 ;;
        unsafe) fail 'Invalid CHRONO_TOOL_CHANNEL.' ;;
        exact) return 0 ;;
        invalid) fail 'CHRONO_TOOL_CHANNEL expects stable, preview or an exact v tag.' ;;
    esac
}
select_tool() {
    case "$disabled" in *\"http:$1\"*) disabled_tool=1 ;; *) disabled_tool=0 ;; esac
    case "$disabled_tool:${CHRONO_TOOL_CHANNEL+x}" in
        0:) selector=$2 ;;
        0:x) selector=$CHRONO_TOOL_CHANNEL ;;
        1:) return 1 ;;
        1:x) return 1 ;;
    esac
    case "$selector" in
        pinned) dynamic=0 ;;
        *) dynamic=1 ;;
    esac
}
select_platform() {
    case "$1" in
        Linux-x86_64) platform=linux-x64; asset=linux-x86_64; seed_sha=$2; other_platform=macos-arm64 ;;
        Darwin-arm64) platform=macos-arm64; asset=macos-aarch64; seed_sha=$3; other_platform=linux-x64 ;;
        *) fail 'Unsupported installation platform.' ;;
    esac
}
order_checksums() {
    case "$1" in
        linux-x64) linux=$2; macos=$3 ;;
        macos-arm64) linux=$3; macos=$2 ;;
    esac
}
more_release_pages() {
    case "$1" in
        next) return 0 ;;
        done) return 1 ;;
        *) fail "Unexpected release page state: $1" ;;
    esac
}
accept_checksum() {
    if [ "$1" = "$2" ]; then
        return 0
    else
        fail "SHA-256 mismatch for $3"
    fi
}
publish_selection() {
    # $1 is the staged selection, $2 the mv destination, $3 the file to remove.
    # Installation, digest and path failures keep the previous file by exiting before this call.
    if [ -s "$1" ]; then
        mv -f "$1" "$2"
    else
        rm -f "$3"
    fi
}
